    ensures
        ({
            let logical = Map::<u64, Seq<Seq<u8>>>::empty().insert(7u64, seq![seq![42u8]]);
            let old_view = RunView { mapping: Map::<u64, SlotRun>::empty().insert(7u64, SlotRun { start: 10, span: 1 }), logical };
